import sys

input = sys.stdin.read
data = input().split()

def min_product(a, b, x, y, n):
    if n >= (a - x) + (b - y):
        return max(x * b, a * y)
    else:
        a -= min(n, a - x)
        b -= min(n, b - y)
        return a * b

def main():
    t = int(data[0])
    index = 1
    results = []
    for _ in range(t):
        a = int(data[index])
        b = int(data[index + 1])
        x = int(data[index + 2])
        y = int(data[index + 3])
        n = int(data[index + 4])
        results.append(min_product(a, b, x, y, n))
        index += 5

    for result in results:
        print(result)

if __name__ == "__main__":
    main()
